static const KfIconDef* KfFindIconConsistent(const char* name) {
    if (!name || !name[0]) return nullptr;
    for (const auto& d : k_kfIconsC)
        if (strcmp(d.name, name) == 0) return &d;
    return KfFindIcon(name);
}
